// solaria-boq-files.mjs
// Run ONCE from your project root (the folder with package.json):
//   node solaria-boq-files.mjs
// Then HARD-REFRESH the browser (Ctrl+Shift+R).
// Rewrites the entire src/ tree so no stale file can be left behind.

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const files = {"src/App.jsx": "", "src/index.css": "", "src/main.jsx": "", "src/theme.js": "", "src/components/Modal.jsx": "", "src/components/PrModal.jsx": "", "src/components/ReceiveModal.jsx": "", "src/components/Sidebar.jsx": "", "src/components/ui.jsx": "", "src/data/seed.js": "", "src/engine/format.js": "", "src/engine/match.js": "", "src/engine/reconcile.js": "", "src/engine/schedule.js": "", "src/pages/BoqPage.jsx": "", "src/pages/CataloguePage.jsx": "", "src/pages/Overview.jsx": "", "src/pages/PurchaseRequestsPage.jsx": "", "src/pages/ReconciliationPage.jsx": "", "src/pages/SchedulePage.jsx": "", "src/pages/SuppliersPage.jsx": "", "src/store/StoreContext.jsx": "", "README.md": "", "FILE_LIST.md": ""};

let count = 0;
for (const [rel, b64] of Object.entries(files)) {
  const target = join(root, rel);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, Buffer.from(b64, 'base64'));
  console.log('  wrote', rel);
  count++;
}
console.log('\nDone. ' + count + ' files written.');
console.log('If the dev server is running, it should hot-reload. If not: npm run dev');
